import React, { createContext, useContext, useState } from 'react';

const AuthContext = createContext(null);

export function AuthProvider({ children, store, onUpdate }) {
  const [currentUser, setCurrentUser] = useState(() => {
    try {
      const s = sessionStorage.getItem('educore_session');
      return s ? JSON.parse(s) : null;
    } catch { return null; }
  });

  function login(username, password) {
    const normalizedUsername = username?.trim().toLowerCase();
    const normalizedPassword = password?.trim();
    const user = store.users.find(
      u => u.username.toLowerCase() === normalizedUsername && u.password === normalizedPassword
    );
    if (!user) return { success: false, error: 'Invalid ID or password' };
    sessionStorage.setItem('educore_session', JSON.stringify(user));
    setCurrentUser(user);
    return { success: true, user };
  }

  function logout() {
    sessionStorage.removeItem('educore_session');
    setCurrentUser(null);
  }

  function changePassword(userId, oldPass, newPass) {
    const user = store.users.find(u => u.id === userId);
    if (!user) return { success: false, error: 'User not found' };
    if (user.password !== oldPass) return { success: false, error: 'Current password is incorrect' };
    const updatedUsers = store.users.map(u =>
      u.id === userId ? { ...u, password: newPass, mustChangePassword: false } : u
    );
    const updated = { ...store, users: updatedUsers };
    onUpdate(updated);
    const updatedUser = { ...user, password: newPass, mustChangePassword: false };
    sessionStorage.setItem('educore_session', JSON.stringify(updatedUser));
    setCurrentUser(updatedUser);
    return { success: true };
  }

  return (
    <AuthContext.Provider value={{ currentUser, login, logout, changePassword }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
